import sys

def count_palindromes(s, n):
    MOD = 10007
    m = len(s)
    dp = [[0] * (n + 1) for _ in range(m + 1)]
    dp[0][0] = 1

    for i in range(1, m + 1):
        for j in range(n + 1):
            dp[i][j] = dp[i - 1][j - 1] * 26 % MOD
            if j > 0:
                dp[i][j] = (dp[i][j] + dp[i - 1][j]) % MOD
            if s[i - 1] == s[m - i]:
                dp[i][j] = (dp[i][j] + dp[m - i][j]) % MOD
            else:
                if j > 0:
                    dp[i][j] = (dp[i][j] + dp[m-i][j-1]) % MOD

    return dp[m][n]

input = sys.stdin.read().strip().split()
s = input[0]
n = int(input[1])
print(count_palindromes(s, n))
